Stack using templates
                      Stack.h:
template <class T>
class Stack {
public:
    Stack();
    int empty(void); // 1=true, 0=false
    int push(T &); // 1=successful,0=stack overflow
    T pop(void);
    T peek(void);
    ~Stack();
private:
    int top;
    T* nodes;
};

Stack using templates
                  Stack.cpp
 #include <iostream.h>
 #include <stdlib.h>
 #include "Stack.cpp"

 #define MAXSTACKSIZE 50

 template <class T>
 Stack<T>::Stack()
 {
     top = -1;
     nodes = new T[MAXSTACKSIZE];
 }

Stack using templates
                  Stack.cpp
 template <class T>
 Stack<T>::~Stack()
 {
     delete nodes;
 }

 template <class T>
 int Stack<T>::empty(void)
 {
     if( top < 0 ) return 1;
     return 0;
 }

Stack using templates
                  Stack.cpp
 template <class T>
 int Stack<T>::push(T& x)
 {
     if( top < MAXSTACKSIZE ) {
         nodes[++top] = x;
         return 1;
     }
     cout << "stack overflow in push.\n";
     return 0;
 }

Stack using templates
                  Stack.cpp
 template <class T>
 T Stack<T>::pop(void)
 {
     T x;
     if( !empty() ) {
          x = nodes[top--];
          return x;
     }
     cout << "stack underflow in pop.\n";
     return x;
 }

