    C++ code for delete

    TreeNode<int>* remove(TreeNode<int>* tree, int info)
    {
        TreeNode<int>* t;
        int cmp = info - *(tree->getInfo());
        if( cmp < 0 ){
            t = remove(tree->getLeft(), info);
            tree->setLeft( t );
        }
        else if( cmp > 0 ){
            t = remove(tree->getRight(), info);
